  align-items: flex-start;
  justify-content: center;
  padding: 48px 16px 64px;
  line-height: 1.5;
}

/* ── App Shell ── */
#app {
  width: 100%;
  max-width: 680px;
}

/* ── Quiz Header ── */
.quiz-header {
  text-align: center;
  margin-bottom: 40px;
}

.quiz-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--accent-dim);
  border: 1px solid rgba(108, 127, 242, 0.3);
  color: var(--accent);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 4px 12px;
  border-radius: 99px;
  margin-bottom: 16px;
}

.quiz-title {
  font-size: clamp(24px, 5vw, 34px);
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--text-primary);
  margin-bottom: 8px;
}

.quiz-subtitle {
  font-size: 14px;
  color: var(--text-secondary);
}

/* ── Form ── */
.quiz-form {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* ── form-field (question card) ── */
.form-field {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: var(--shadow);
  transition: border-color var(--transition);
}

.form-field:focus-within {
  border-color: var(--border-focus);
}

.question-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 12px;
}

.question-number {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--accent);
  background: var(--accent-dim);
  border-radius: 99px;
  padding: 2px 10px;
}

.multi-badge {
  font-size: 11px;
  color: var(--text-muted);
  font-weight: 500;
}

.question-text {
  font-size: 16px;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 8px;
  line-height: 1.4;
}

/* ── Help Text ── */
.help-text {
  display: flex;
  align-items: flex-start;
  gap: 7px;
  font-size: 12.5px;
  color: var(--text-secondary);
  background: rgba(255,255,255,0.03);
  border-left: 3px solid var(--accent);
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
  padding: 8px 12px;
  margin-bottom: 16px;
  line-height: 1.45;
}

.help-text svg {
  flex-shrink: 0;
  margin-top: 1px;
  color: var(--accent);
}

/* ── Options List ── */
.options-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  list-style: none;
}

/* ── Checkbox Option ── */
.option-label {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  background: var(--bg-card);
  cursor: pointer;
  transition: background var(--transition), border-color var(--transition), transform var(--transition);
  user-select: none;
}

.option-label:hover {
  background: var(--bg-hover);
  border-color: var(--border-focus);
  transform: translateX(2px);
}

.option-label:has(input:checked) {
  background: var(--accent-dim);
  border-color: var(--accent);
}

/* Hide native checkbox */
.option-label input[type="checkbox"] {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

/* Custom checkbox */
.custom-checkbox {
  flex-shrink: 0;
  width: 18px;
  height: 18px;
  border-radius: 4px;
  border: 2px solid var(--border-focus);
  background: transparent;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background var(--transition), border-color var(--transition);
}

.option-label input:checked + .custom-checkbox {
  background: var(--accent);
  border-color: var(--accent);
}

.custom-checkbox svg {
  display: none;
  color: #fff;
}

.option-label input:checked + .custom-checkbox svg {
  display: block;
}

.option-text {
  font-size: 14px;
  color: var(--text-primary);
  font-weight: 500;
}

.option-label:has(input:checked) .option-text {
  color: var(--accent-hover);
}

/* ── Submit Button ── */
.submit-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
  padding: 14px 24px;
  margin-top: 4px;
  background: var(--accent);
  color: #fff;
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.01em;
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
  box-shadow: 0 4px 16px rgba(108, 127, 242, 0.35);
}

.submit-btn:hover {
  background: var(--accent-hover);
  transform: translateY(-1px);
  box-shadow: 0 6px 24px rgba(108, 127, 242, 0.5);
}

.submit-btn:active {
  transform: translateY(0);
}

/* ── Result Banner ── */
.result-banner {
  display: none;
  align-items: flex-start;
  gap: 14px;
  padding: 18px 20px;
  border-radius: var(--radius);
  border: 1px solid;
  font-size: 14px;
  line-height: 1.5;
}

.result-banner.show { display: flex; }

.result-banner.pass {
  background: var(--success-dim);
  border-color: var(--success);
  color: var(--success);
}

.result-banner.fail {
  background: var(--error-dim);
  border-color: var(--error);
  color: var(--error);
}

.result-banner svg { flex-shrink: 0; margin-top: 1px; }

.result-banner strong { font-weight: 700; }

.result-banner p { color: var(--text-secondary); margin-top: 2px; font-size: 13px; }

/* ── Validation ── */
.form-field.error {
  border-color: var(--error);
}

.field-error {
  font-size: 12px;
  color: var(--error);
  margin-top: 10px;
  display: none;
}

.form-field.error .field-error { display: block; }

/* ── Focus ring for accessibility ── */
.option-label:focus-within {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}
