// ── Quiz Data ──────────────────────────────────────────────────────────────
const QUESTIONS = [
  {
    id: "q1",
    number: "Question 1",
    text: "Which of the following are statically typed programming languages?",
    helpText:
      "Static typing means variable types are checked at compile time rather than at runtime. A language can be statically typed even if it supports type inference.",
    options: [
      { id: "q1-a", value: "rust", label: "Rust" },
      { id: "q1-b", value: "python", label: "Python" },
      { id: "q1-c", value: "typescript", label: "TypeScript" },
      { id: "q1-d", value: "java", label: "Java" },
    ],
    correct: ["rust", "typescript", "java"],
  },
  {
    id: "q2",
    number: "Question 2",
    text: "Which programming languages are primarily used for systems programming?",
    helpText: null,
    options: [
      { id: "q2-a", value: "c", label: "C" },
      { id: "q2-b", value: "r", label: "R" },
      { id: "q2-c", value: "rust", label: "Rust" },
      { id: "q2-d", value: "cpp", label: "C++" },
    ],
    correct: ["c", "rust", "cpp"],
  },
  {
    id: "q3",
    number: "Question 3",
    text: "Which of the following languages support first-class functions?",
    helpText: null,
    options: [
      { id: "q3-a", value: "javascript", label: "JavaScript" },
      { id: "q3-b", value: "haskell", label: "Haskell" },
      { id: "q3-c", value: "cobol", label: "COBOL" },
      { id: "q3-d", value: "python", label: "Python" },
    ],
    correct: ["javascript", "haskell", "python"],
  },
];

// ── Utility helpers ────────────────────────────────────────────────────────
const el = (tag, attrs = {}, ...children) => {
  const node = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (k === "className") node.className = v;
    else if (k === "htmlFor") node.setAttribute("for", v);
    else if (k.startsWith("on") && typeof v === "function")
      node.addEventListener(k.slice(2).toLowerCase(), v);
    else node.setAttribute(k, v);
  }
  for (const child of children) {
    if (child == null) continue;
    node.append(typeof child === "string" ? document.createTextNode(child) : child);
  }
  return node;
};

const svgIcon = (path, size = 16) => {
  const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  svg.setAttribute("width", size);
  svg.setAttribute("height", size);
  svg.setAttribute("viewBox", "0 0 24 24");
  svg.setAttribute("fill", "none");
  svg.setAttribute("stroke", "currentColor");
  svg.setAttribute("stroke-width", "2.2");
  svg.setAttribute("stroke-linecap", "round");
  svg.setAttribute("stroke-linejoin", "round");
  const p = document.createElementNS("http://www.w3.org/2000/svg", "path");
  p.setAttribute("d", path);
  svg.appendChild(p);
  return svg;
};

// ── Component: CheckboxOption ──────────────────────────────────────────────
function CheckboxOption({ questionId, option }) {
  const input = el("input", {
    type: "checkbox",
    id: option.id,
    name: questionId,
    value: option.value,
  });

  const checkmark = el("span", { className: "custom-checkbox" },
    svgIcon("M20 6L9 17l-5-5", 12)
  );

  const label = el("label", { className: "option-label", htmlFor: option.id },
    input,
    checkmark,
    el("span", { className: "option-text" }, option.label)
  );

  return label;
}

// ── Component: HelpText ────────────────────────────────────────────────────
function HelpText({ text }) {
  return el("p", { className: "help-text" },
    svgIcon("M12 22c5.523 0 10-4.477 10-10S17.523 2 12 2 2 6.477 2 12s4.477 10 10 10zM12 8v4M12 16h.01", 15),
    text
  );
}

// ── Component: QuestionCard ────────────────────────────────────────────────
function QuestionCard({ question }) {
  const optionNodes = question.options.map((opt) =>
    el("li", {}, CheckboxOption({ questionId: question.id, option: opt }))
  );

  const children = [
    el("div", { className: "question-meta" },
      el("span", { className: "question-number" }, question.number),
      el("span", { className: "multi-badge" }, "Select all that apply")
    ),
    el("p", { className: "question-text" }, question.text),
    question.helpText ? HelpText({ text: question.helpText }) : null,
    el("ul", { className: "options-list", role: "group", "aria-label": question.text },
      ...optionNodes
    ),
    el("p", { className: "field-error", id: `${question.id}-error` },
      "Please select at least one answer."
    ),
  ];

  return el("div", { className: "form-field", id: `field-${question.id}`, role: "group" },
    ...children.filter(Boolean)
  );
}

// ── Component: ResultBanner ────────────────────────────────────────────────
function ResultBanner() {
  const icon = svgIcon("", 20); // placeholder, updated on show
  const heading = el("strong", {});
  const body = el("p", {});
  const textWrap = el("div", {}, heading, body);
  const banner = el("div", { className: "result-banner", role: "alert" }, icon, textWrap);

  banner.show = ({ pass, score, total }) => {
    banner.className = `result-banner show ${pass ? "pass" : "fail"}`;
    const iconPath = pass
      ? "M22 11.08V12a10 10 0 11-5.93-9.14M22 4L12 14.01l-3-3"
      : "M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0zM12 9v4M12 17h.01";
    icon.querySelector("path")?.remove();
    const p = document.createElementNS("http://www.w3.org/2000/svg", "path");
    p.setAttribute("d", iconPath);
    icon.appendChild(p);
    heading.textContent = pass
      ? `Great work! You scored ${score} / ${total}.`
      : `Not quite — you scored ${score} / ${total}.`;
    body.textContent = pass
      ? "You answered all questions correctly."
      : "Review the highlighted questions and try again.";
  };

  return banner;
}

// ── Component: QuizApp ─────────────────────────────────────────────────────
function QuizApp() {
  const questionCards = QUESTIONS.map((q) => QuestionCard({ question: q }));
  const resultBanner = ResultBanner();

  const submitBtn = el("button", { className: "submit-btn", type: "submit" },
    svgIcon("M9 12l2 2 4-4M7.835 4.697a3.42 3.42 0 001.946-.806 3.42 3.42 0 014.438 0 3.42 3.42 0 001.946.806 3.42 3.42 0 013.138 3.138 3.42 3.42 0 00.806 1.946 3.42 3.42 0 010 4.438 3.42 3.42 0 00-.806 1.946 3.42 3.42 0 01-3.138 3.138 3.42 3.42 0 00-1.946.806 3.42 3.42 0 01-4.438 0 3.42 3.42 0 00-1.946-.806 3.42 3.42 0 01-3.138-3.138 3.42 3.42 0 00-.806-1.946 3.42 3.42 0 010-4.438 3.42 3.42 0 00.806-1.946 3.42 3.42 0 013.138-3.138z", 18),
    "Submit Answers"
  );

  const form = el("form", { className: "quiz-form", noValidate: "" },
    ...questionCards,
    submitBtn,
    resultBanner
  );

  form.addEventListener("submit", (e) => {
    e.preventDefault();
    let allValid = true;
    let score = 0;

    for (const question of QUESTIONS) {
      const fieldEl = document.getElementById(`field-${question.id}`);
      const checked = [...form.querySelectorAll(`input[name="${question.id}"]:checked`)]
        .map((i) => i.value);

      const isEmpty = checked.length === 0;
      fieldEl.classList.toggle("error", isEmpty);
      if (isEmpty) { allValid = false; continue; }

      const correct = new Set(question.correct);
      const isCorrect =
        checked.length === correct.size && checked.every((v) => correct.has(v));
      if (isCorrect) score++;
    }

    if (!allValid) return;

    resultBanner.show({ pass: score === QUESTIONS.length, score, total: QUESTIONS.length });
    resultBanner.scrollIntoView({ behavior: "smooth", block: "nearest" });
  });

  // Clear error state on change
  form.addEventListener("change", (e) => {
    if (e.target.type !== "checkbox") return;
    const name = e.target.name;
    const fieldEl = document.getElementById(`field-${name}`);
    const anyChecked = form.querySelector(`input[name="${name}"]:checked`);
    if (anyChecked) fieldEl.classList.remove("error");
  });

  const header = el("header", { className: "quiz-header" },
    el("div", { className: "quiz-badge" },
      svgIcon("M10 20l4-16m4 4l4 4-4 4M6 16l-4-4 4-4", 13),
      "Computer Languages Quiz"
    ),
    el("h1", { className: "quiz-title" }, "How Well Do You Know Programming Languages?"),
    el("p", { className: "quiz-subtitle" }, "3 questions · Select all correct answers · Instant results")
  );

  const root = el("div", { id: "app" }, header, form);
  return root;
}

// ── Mount ──────────────────────────────────────────────────────────────────
document.addEventListener("DOMContentLoaded", () => {
  document.body.appendChild(QuizApp());
});

